"""
apply_revised.py - writes report/paper/revised_wording.tex: final.tex with the prose the team
reworded in IndicBridge_Research_Paper_Revised.pdf (13 Nov 2026). Citations, labels and equations
are kept from final.tex. Each FIX comment marks a factual or typing slip corrected in the
revised text; everything else is the team's wording as written.

    python3 report/word/apply_revised.py <changed.json>
"""
import json
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
SRC = os.path.join(ROOT, "report/paper/final.tex")
OUT = os.path.join(ROOT, "report/paper/revised_wording.tex")
old = {o["k"]: o["tex"] for o in json.load(open(sys.argv[1]))}

NEW = {
    10: r"""Pillai \emph{et al.}\ studied multistage fine-tuning for Malasar, a very low-resource Dravidian language. They first adapted Whisper using Tamil speech and then fine-tuned it for Malasar. Their reported WER was 51.9\%, which was 4.5 points lower than direct fine-tuning; removing punctuation reduced it further to 47.3\% \cite{pillai2026multistage}. At that very time, it also evaluates only one pivot--target pair. Without a comparison against a distant or a non-Indic pivot, it isn't possible to tell how much of the gain comes specifically from the relationship between Tamil and Malasar.""",  # FIX: "only" restored
    13: r"""Bhogale \emph{et al.}\ presented Vistaar, a collection of benchmarks covering different Indian languages and domains, and trained IndicWhisper on multilingual Indian speech \cite{bhogale2023vistaar}. Their results also show that model rankings can change across benchmarks. This is one reason our evaluation uses both FLEURS and Kathbath instead of relying on a single test set. FLEURS provides parallel speech across many languages \cite{conneau2023fleurs}, whereas Kathbath provides the Indian language evaluation resource \cite{javed2023indicsuperb}. IndicWhisper uses joint multilingual training, whereas our work studies sequential pivot-to-target adaptation.""",
    14: r"""Table~\ref{tab:comparison} will summarize the studies as discussed above, together with the limitation most relevant to the IndicBridge research questions.""",
    15: r"""There are three gaps that are relevant to this work. At first, multistage fine-tuning has been shown to help low-resource ASR, and previous research had linked transfer quality to language-family exposure. What was not tested directly is whether a related pivot performs better than a more distant, non-Indic one when the audio hours and training schedule are matched.""",
    16: r"""Second, languages without a dedicated token in the pre-trained model need more attention. Odia is a useful test case because Whisper can represent its script but doesn't provide an Odia language token. Therefore, it is necessary to examine if borrowing a token from another language affects recognition, both before and after fine-tuning.""",
    17: r"""Third, the evaluation across Indic scripts needs some care.""",
    20: r"""IndicBridge addresses these questions through a controlled set of experiments using Whisper-base. Hindi is used as the Indic pivot and English as a distant, non-Indic control. We keep the model and the optimizer and decoding setup and scoring procedure consistent and accurate across every single run.""",
    21: r"""Adapting a multilingual speech model to a low-resource language is not simply a matter of adding a few more training steps. A small target corpus may not contain enough examples for the model to learn the language's pronunciation, vocabulary and writing conventions. One of the possible responses is adapting the model first on an intermediate language and then continuing the training on the target. What remains a question is why this extra stage helps. The pivot may share useful properties with the target, or the model may benefit simply from seeing more speech before target-language training.""",
    22: r"""That distinction affects how a pivot should be chosen. A practitioner might look for a related language or might choose whichever language has the largest available corpus. Earlier work reported an improvement for Tamil-to-Malasar adaptation but did not include a distant-language control pivot \cite{pillai2026multistage}. The aim is to test if Hindi provides an advantage over an equal duration of English pivot, not to assume in advance that language family alone explains any gain.""",  # FIX: "or not to assume" -> ", not to assume"
    23: r"""The experimental pipeline is shown in Fig.~\ref{fig:arch}. Direct fine-tuning was the reference condition and had started from a fresh LoRA adapter rather than the one learned on a pivot.""",
    24: r"""There were 25 runs in total: six zero-shot configurations, two pivot training runs, six pivot-only evaluations, three direct target runs, three Hindi-to-target runs, three English-to-target runs and two extra Odia-token runs. Bengali was selected as the default borrowed token before any results were examined; Assamese and Hindi were added as ablations rather than being chosen after seeing which one scored best. We also used a simple gate before starting the target-language grid: the Hindi pivot had to improve on zero-shot Hindi first. It did, reducing WER from 154.7 to 41.0 on FLEURS and from 137.0 to 44.0 on Kathbath. A resumable queue runs the jobs one after another on the M4, records failures and continues after a crash or sleep.""",
    26: r"""We removed clips shorter than two seconds or longer than 30 seconds, as well as rows containing annotation tags such as \texttt{<unintelligible>}. The tag filter did the job by removing 1,044 Hindi rows, 704 Odia rows, 285 Kannada rows and 157 Marathi rows. We limited the Indian-language training data to 50 clips per speaker; English used a limit of 120 because its speakers had longer recordings. Whisper's decoder has a 448-token context limit, so the training labels were capped at 443 tokens to leave space for the task and language special tokens. This removed 1,076 Odia clips and 158 Kannada clips.""",  # FIX: "about 448" -> "a 448-token"
    29: r"""In multistage runs, target training continued from the pivot adapter, and the direct runs began with a fresh adapter; the remaining settings are listed in Table~\ref{tab:setup}. We chose Whisper-base for a practical reason. On the M4, Whisper-small trained at a rate of 1.35 clips/s, which put the grid near 49 hours at the step budget used here. Whisper-base reached about 4.54 clips/s, which brought the estimate to roughly 15 hours. The absolute WER of base is consequently higher than it would be with a larger model.""",
    30: r"""The only real problem is memory usage, and we have put a limit on the MPS allocation at around 9.5 GB so that the machine does not start swapping heavily. Variable label lengths caused out-of-memory errors twice in the Hindi pivot, because MPS cached a separate computation graph for each label length. The labels were padded to multiples of 64, leading to seven different shapes. The micro-batch/accumulation layout was changed from 4-by-4 to 2-by-8, but the effective batch of 16 remained the same.""",  # FIX: garbled out-of-memory sentence
    35: r"""We used paired bootstrap sampling to estimate 95\% confidence intervals \cite{bisani2004bootstrap}. For each comparison, 1,000 test-utterance resamples were drawn. Both systems were scored on the same resampled utterances, and corpus-level WER was recalculated each time. The 2.5th and 97.5th percentiles formed the interval. During the analysis, we found that using one shared random stream had made a borderline interval depend on the order in which comparisons were calculated. We corrected this by giving a fixed seed to each comparison. For target-wise interactions, the two language test sets were resampled independently. Each training configuration was run with one seed only, so these intervals don't measure variation across independent training runs.""",
    36: r"""To deploy, we wrote a converter that merges each LoRA adapter into Whisper-base and converts the resulting weights to MLX format \cite{mlx2023}, checking that each tensor name mapped to the source model. The first results from MLX did not match PyTorch. We put part of the difference down to timestamping. The adapters were trained without timestamps, but the original MLX path enabled them. In a 20-clip debugging check, Kannada CER went from 35.6 to 24.4 with timestamps off. Some clips had entered loops of repetition, and hence we made use of the Whisper temperature fallback to deal with such instances. In this regard, our MLX WER was within 2.5 points of PyTorch in the benchmark of 100 clips. We also generated the FP16 and 4-bit models (143.7 MB and 42.2 MB) and tested the FP16 model without an internet connection.""",  # FIX: "did support them", sentence fragment, "just 2.5 points behind"
    41: r"""Hindi enhances all three languages, including Kannada, which is part of the Dravidian language family. On FLEURS, no confidence interval for the differences between the Hindi-specific gains excludes zero, i.e., none of them is statistically significant. On Kathbath, the Hindi-specific gain for Marathi exceeds that of Kannada by 2.7 points (95\% CI: 1.0 to 4.8), and that of Odia by 2.0 points (95\% CI: 0.1 to 4.3); the difference between Kannada and Odia gains is not significant. One possible reason for the improvement of Kannada could be some phonetic or acoustic properties shared by Indian languages. However, these properties were not measured in the present study.""",  # FIX: "is statistically significant, i.e., it does not exclude zero"
    42: r"""The cost of tokenization is high for the Odia language in comparison with the other languages used in the experiment. This language utilizes around 3.09 tokens per letter and 17.6 tokens per word, while the other languages used the same metrics at 1.29 (for Hindi), 1.30 (Marathi) and 1.89 (Kannada). The output limitation is another practical problem: 202 out of 875 Odia FLEURS references (23.1\%) were too long to be decoded and were excluded from evaluation. After training, the WER scores become comparable: Bengali 74.5/64.9, Assamese 74.9/65.0 and Hindi 73.8/64.6 on FLEURS/Kathbath.""",
    45: r"""Each configuration used one training seed, so the bootstrap intervals capture variation in the test samples, not variation between independent training runs. We used Whisper-base and seeded subsets of two test datasets, and the large number of Odia references that exceed the decoder limit means that the Odia scores describe only the references the model could produce. Like Hindi, Marathi also uses the Devanagari script, making it difficult to separate script effects from family effects. Lastly, the intended native speakers' listening notes and error sheets were not available in time for analysis; hence, we cannot state what error classes the Hindi pivot sorted out.""",
    46: r"""This study compares direct fine-tuning with two-stage adaptation via Hindi and English for Marathi, Odia and Kannada. It was found that Hindi had a positive impact on WER for all three languages, whilst English did not produce any significant improvements given the same 45-hour pivot budget. This is important, as we can see that there are benefits to using Hindi as a pivot for languages outside of Indo-Aryan (Kannada). Due to inconsistencies at the family level between FLEURS and Kathbath, and the differences in domains for the recordings and the model's existing familiarity with the language for the English control, it cannot be said that the improvements are purely due to linguistic relatedness.""",  # FIX: "lack of familiarity" inverted the confound
    47: r"""There are many clear improvements to be made. Firstly, a Dravidian pivot such as Tamil or Telugu could be used to test for transfer in the opposite direction, and the addition of Marathi-to-Odia and Kannada-to-Odia runs would increase the comparisons made for Odia. More training seeds should also be used alongside larger Whisper models to see how consistent the improvements are. In future, it would be good to have an experiment that isolates the effect of script similarities versus family similarities, and to look at different tokenizers which represent Odia more efficiently. Listening notes from native speakers and complete error sheets should also be included so that the paper can state what types of errors were corrected.""",
}
SENTENCES = [  # paragraph 28 holds an equation, so its two prose parts are edited in place
    (r"""We used the 74-million-parameter Whisper-base model as the starting
point \cite{radford2023whisper}. Its original weights were kept frozen,
and LoRA adapters""", r"""We used the 74-million-parameter Whisper-base model as the starting
point \cite{radford2023whisper}. Its original weights were kept frozen, and
LoRA adapters"""),
]

s = open(SRC, encoding="utf-8").read()
for k, new in NEW.items():
    assert s.count(old[k]) == 1, (k, s.count(old[k]), old[k][:60])
    s = s.replace(old[k], new)
for a, b in SENTENCES:
    assert s.count(a) == 1, a[:60]
    s = s.replace(a, b)
open(OUT, "w", encoding="utf-8").write(s)
print("wrote", OUT, len(NEW), "paragraphs")
